<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { fly, fade } from 'svelte/transition';
  import Coworkers from '../lib/Coworkers.svelte';
  import SidebarCoworkers from '../lib/SidebarCoworkers.svelte';
  import Office from '../lib/office/Office.svelte';
  import Sprite from '../lib/office/Sprite.svelte';
  import Icon from '../lib/ui/Icon.svelte';
  import { Terminal } from '@xterm/xterm';
  import { FitAddon } from '@xterm/addon-fit';
  import '@xterm/xterm/css/xterm.css';

  // Development uses Vite's same-origin proxy so the browser never needs a
  // separate cross-port connection to the local execution service.
  const api = import.meta.env.VITE_PIXEL_HARNESS_API || '/api/v1';
  const recipes = {
    skin: ['umber-02', 'sienna-01', 'golden-01'], hair: ['short-auburn-03', 'curl-dark-01', 'crop-ink-01'],
    top: ['cardigan-navy-01', 'shirt-cream-01', 'overshirt-moss-01'], accent: ['moss-01', 'terracotta-01', 'indigo-01']
  };
  let board: any[] = [], environments: any[] = [], selectedTaskId = '', historicalExecution: any = null;
  $: viewExecution = execution && execution.employee_id === colleague?.employee_id && (!selectedTaskId || execution.task_id === selectedTaskId) ? execution : historicalExecution;
  async function mutate(path:string, body:any, method='PATCH'){try{await call(path,{method,body:JSON.stringify(body)});await load();}catch(e){error=(e as Error).message;}}
  function openPerson(person:any){focusedEmployee=person;selectedTaskId=person.assignment?.task_id || '';historicalExecution=board.find(t=>t.task_id===selectedTaskId)?.attempt || null;selected=projects.find(p=>p.project_id===person.assignment?.project_id)||selected;panel='office';sidebarPreference=true;dock='activity';}
  async function openTask(task:any){selected=projects.find(p=>p.project_id===task.project_id);selectedTaskId=task.task_id;focusedEmployee=staff.find(p=>p.employee_id===task.employee_id)||null;historicalExecution=task.attempt;panel=task.attempt?'office':'projects';sidebarPreference=true;dock='activity';await tick();document.getElementById(`task-${task.task_id}`)?.scrollIntoView({block:'center'});}
  let systemReduced=false;
  let compact=false, sidebarPreference: boolean | null=null;
  $: sidebarOpen=sidebarPreference ?? !compact;
  onMount(()=>{const media=matchMedia('(max-width: 1000px)');const update=()=>compact=media.matches;update();media.addEventListener('change',update);return()=>media.removeEventListener('change',update);});
  $: motionOff=Boolean(prefs.reduced_motion)||systemReduced;
  let poseOverrides:Record<string,string>={};
  let focusedEmployee: any = null, dock = 'activity', showSettings = false;
  let readiness: any = null, execution: any = null, launchPrompt = '', followUp = '', terminalHost: HTMLDivElement, xterm: Terminal | null = null, fit: FitAddon | null = null, terminalRendered = 0;
  let token = '', projects: any[] = [], staff: any[] = [], prefs: any = { map_treatment: 'warm', reduced_motion: 0 }, inbox: any[] = [];
  let selected: any = null, panel = 'office', roomId = 'office', actor = { x: 12, y: 7 }, error = '', query = '', activeRequest: any = null, editing: any = null, folderPath = '', browse: any = null;
  async function call(path: string, options: RequestInit = {}) { const response = await fetch(`${api}${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...(token && /^https?:/.test(api) ? { 'X-Pixel-Harness-Token': token } : {}), ...(options.headers || {}) } }); const value = await response.json(); if (!response.ok) throw new Error(`${value.error.code}: ${value.error.message}`); return value.data; }
  async function load(attempt = 0) {
    try {
      const result = await Promise.all([call('/projects'), call('/staff'), call('/office/preferences'), call('/inbox'), call('/codex/readiness'), call('/executions/active'), call('/board'), call('/environments')]);
      [projects, staff, prefs, inbox, readiness, execution, board, environments] = result;
      selected = projects.find((project) => project.project_id === selected?.project_id) || projects.find((project) => project.status === 'active') || projects[0] || null;
      error = '';
    } catch (e) { if (attempt < 12) { await new Promise((resolve) => setTimeout(resolve, 250)); return load(attempt + 1); } error = (e as Error).message; }
  }
  onMount(() => { const found = new URLSearchParams(location.hash.slice(1)).get('token'); token = found || ''; load(); const timer=window.setInterval(async()=>{try{[execution,board,staff,environments]=await Promise.all([call('/executions/active'),call('/board'),call('/staff'),call('/environments')]);writeTerminal();}catch{}},1000); return()=>clearInterval(timer); });
  function terminalSurface(node: HTMLDivElement) { terminalHost=node; xterm=new Terminal({ theme:{background:'#1b1d25',foreground:'#d7d3c8',cursor:'#d7d3c8'}, fontSize:11, fontFamily:'ui-monospace, SFMono-Regular, Menlo, monospace', convertEol:true, scrollback:4000 }); fit=new FitAddon(); xterm.loadAddon(fit); xterm.open(node); fit.fit(); const resize=()=>{fit?.fit(); if(execution?.attempt_id) void call(`/executions/${execution.attempt_id}/resize`,{method:'POST',body:JSON.stringify({rows:xterm?.rows,cols:xterm?.cols})}).catch(()=>{});}; const observer=new ResizeObserver(resize);observer.observe(node);const input=xterm.onData((data)=>{if(viewExecution?.attempt_id===execution?.attempt_id&&execution?.terminal?.attached)void call(`/executions/${execution.attempt_id}/terminal-input`,{method:'POST',body:JSON.stringify({data})}).catch((e)=>error=e.message);});writeTerminal();return{destroy(){observer.disconnect();input.dispose();xterm?.dispose();xterm=null;fit=null;terminalRendered=0;}}; }
  function writeTerminal(){const text=viewExecution?.terminal?.terminal||'';if(xterm&&text.length>terminalRendered){xterm.write(text.slice(terminalRendered));terminalRendered=text.length;}if(xterm&&text.length<terminalRendered){xterm.reset();xterm.write(text);terminalRendered=text.length;}}
  async function launch(task:any){try{if(!task.assignments?.[0])throw new Error('Assign a colleague before launching.');const plan=task.plans?.find((item:any)=>item.status==='approved');if(!plan)throw new Error('PLAN_APPROVAL_REQUIRED: approve a plan version before launch.');error='';execution=await call('/executions',{method:'POST',body:JSON.stringify({task_id:task.task_id,employee_id:task.assignments[0].employee_id,plan_id:plan.plan_id,prompt:launchPrompt.trim()})});focusedEmployee=staff.find(p=>p.employee_id===execution.employee_id);selectedTaskId=task.task_id;historicalExecution=null;dock='terminal';sidebarPreference=true;panel='office';launchPrompt='';await load();}catch(e){const message=(e as Error).message;await load();error=message;}}
  async function stopExecution(){if(!execution?.attempt_id)return;try{await call(`/executions/${execution.attempt_id}/stop`,{method:'POST'});execution=null;historicalExecution=null;terminalRendered=0;await load();}catch(e){error=(e as Error).message;}}
  function openActiveTerminal(){focusedEmployee=staff.find(p=>p.employee_id===execution?.employee_id);selectedTaskId=execution?.task_id || '';historicalExecution=null;dock='terminal';sidebarPreference=true;panel='office';}
  async function setTreatment(map_treatment: 'warm' | 'cool' | 'editorial') { try { prefs = await call('/office/preferences', { method: 'PATCH', body: JSON.stringify({ map_treatment }) }); } catch (e) { error = (e as Error).message; } }
  async function setMotion(event: Event) { try { prefs = await call('/office/preferences', { method: 'PATCH', body: JSON.stringify({ reduced_motion: (event.currentTarget as HTMLInputElement).checked }) }); } catch (e) { error = (e as Error).message; } }
  async function createProject(event: SubmitEvent) { event.preventDefault(); const form = new FormData(event.currentTarget as HTMLFormElement); try { const created = await call('/projects', { method: 'POST', body: JSON.stringify({ name: form.get('name') }) }); await load(); selected = projects.find((project) => project.project_id === created.project_id) || selected; } catch (e) { error = (e as Error).message; } }
  async function createStaff(event: SubmitEvent) { event.preventDefault(); const form = new FormData(event.currentTarget as HTMLFormElement); try { await call('/staff', { method: 'POST', body: JSON.stringify({ name: form.get('name'), title: form.get('title') }) }); await load(); } catch (e) { error = (e as Error).message; } }
  async function saveAppearance(event: SubmitEvent) { event.preventDefault(); const form = new FormData(event.currentTarget as HTMLFormElement); try { await call(`/staff/${editing.employee_id}/appearance`, { method: 'PATCH', body: JSON.stringify(Object.fromEntries(form)) }); editing = null; await load(); } catch (e) { error = (e as Error).message; } }
  async function archive(action: 'archive' | 'reopen') { if (!selected) return; try { await call(`/projects/${selected.project_id}/${action}`, { method: 'POST' }); await load(); } catch (e) { error = (e as Error).message; } }
  async function attachNativeFolder() { if (!selected) return; try { const picked = await call('/folders/native-select', { method: 'POST' }); await call(`/projects/${selected.project_id}/folders`, { method: 'POST', body: JSON.stringify({ path: picked.path }) }); await load(); } catch (e) { const message=(e as Error).message; if(!message.startsWith('FOLDER_SELECTION_CANCELLED')) error = message; } }
  async function browsePath(path = '') { try { browse = await call(`/folders/browse?path=${encodeURIComponent(path)}`); } catch (e) { error = (e as Error).message; } }
  async function addTask(event: SubmitEvent) { event.preventDefault(); if (!selected) return; const form = new FormData(event.currentTarget as HTMLFormElement); try { await call('/tasks', { method: 'POST', body: JSON.stringify({ project_id: selected.project_id, title: form.get('title'), employee_id: form.get('employee_id') || undefined, folder_ids: form.getAll('folder_ids'), primary_folder_id: form.get('primary_folder_id') }) }); await load(); } catch (e) { error = (e as Error).message; } }
  async function complete(task: any) { try { await call(`/tasks/${task.task_id}/complete`, { method: 'POST' }); await load(); } catch (e) { error = (e as Error).message; } }
  async function reopenTask(task: any) { try { await call(`/tasks/${task.task_id}/reopen`, { method: 'POST' }); await load(); } catch (e) { error = (e as Error).message; } }
  async function useAllProjectFolders(task: any) { const available=selected?.folders.filter((folder:any)=>folder.availability==='available')||[]; const primary=task.folders.find((folder:any)=>folder.is_primary)?.folder_id||available[0]?.folder_id; try { await call(`/tasks/${task.task_id}/folders`, { method: 'PATCH', body: JSON.stringify({ folder_ids: available.map((folder:any)=>folder.folder_id), primary_folder_id: primary }) }); await load(); } catch (e) { error = (e as Error).message; } }
  async function createPlan(event: SubmitEvent, task:any) { event.preventDefault(); const form = new FormData(event.currentTarget as HTMLFormElement); try { await call('/plans',{method:'POST',body:JSON.stringify({project_id:selected.project_id,task_id:task.task_id,summary:form.get('summary'),milestones:String(form.get('milestones')||'').split('\n').filter(Boolean),acceptance:String(form.get('acceptance')||'').split('\n').filter(Boolean),dependencies:[]})});await load(); } catch(e){error=(e as Error).message;} }
  async function approvePlan(plan:any) { try { await call(`/plans/${plan.plan_id}/approve`,{method:'POST',body:JSON.stringify({approved_by:'local user'})});await load(); } catch(e){error=(e as Error).message;} }
  async function saveGuidance(event: SubmitEvent, taskId?: string, replaces?: string) { event.preventDefault(); const form=new FormData(event.currentTarget as HTMLFormElement); try { await call('/guidance',{method:'POST',body:JSON.stringify({project_id:selected.project_id,task_id:taskId,content:form.get('content'),provenance:form.get('provenance'),replaces_guidance_id:replaces})}); await load(); } catch(e){error=(e as Error).message;} }
  async function retireGuidance(guidance:any) { try { await call(`/guidance/${guidance.guidance_id}/retire`,{method:'POST'});await load(); } catch(e){error=(e as Error).message;} }
  async function sendFollowUp() { if(!execution||!followUp.trim())return; try { execution=await call(`/executions/${execution.attempt_id}/messages`,{method:'POST',body:JSON.stringify({content:followUp})});followUp='';await load(); } catch(e){error=(e as Error).message;} }
  async function createRealRequest(event: SubmitEvent) { event.preventDefault();const form=new FormData(event.currentTarget as HTMLFormElement);try {await call('/inbox/requests',{method:'POST',body:JSON.stringify({kind:form.get('kind'),summary:form.get('summary'),detail:form.get('detail'),blocks:form.get('blocks')})});await load();}catch(e){error=(e as Error).message;} }
  async function answerRequest(request:any,event:SubmitEvent) {event.preventDefault();const form=new FormData(event.currentTarget as HTMLFormElement);try{await call(`/inbox/${request.request_id}/answer`,{method:'POST',body:JSON.stringify({response:form.get('response')})});activeRequest=null;await load();}catch(e){error=(e as Error).message;}}
  async function addNotice() { try { await call('/inbox/requests', { method: 'POST', body: JSON.stringify({ kind: 'clarification', summary: 'Codex needs clarification', detail: 'Please clarify the intended implementation direction before continuing.', blocks: 'The active Codex session is waiting for this direction.' }) }); await load(); } catch (e) { error = (e as Error).message; } }
  async function resolveNotice(request: any) { try { await call(`/inbox/${request.request_id}/answer`, { method: 'POST', body: JSON.stringify({ response: request.kind === 'clarification' ? 'Choose alpha. Continue with the approved bounded task.' : 'Acknowledged from the office inbox.' }) }); activeRequest = null; await load(); } catch (e) { error = (e as Error).message; } }
  onMount(()=>{const media=matchMedia('(prefers-reduced-motion: reduce)');systemReduced=media.matches;const change=()=>systemReduced=media.matches;media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});
  function closePanel(){panel='office';}
  function focusSurface(node:HTMLElement, anchored=false){
    const trigger=document.activeElement as HTMLElement;
    if(anchored){const r=trigger?.getBoundingClientRect();const width=Math.min(280,innerWidth-24);node.style.width=`${width}px`;node.style.left=`${Math.max(12,Math.min(innerWidth-width-12,r?.right+10||12))}px`;node.style.top=`${Math.max(70,Math.min(innerHeight-220,(r?.top||80)-20))}px`;}
    let alive=true;
    tick().then(()=>{if(alive)(node.querySelector('button') as HTMLElement || node).focus({preventScroll:true});});
    const trap=(event:KeyboardEvent)=>{if(event.key!=='Tab')return;const items=[...node.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,[tabindex="0"]')].filter(item=>item.getClientRects().length);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}};
    node.addEventListener('keydown',trap);
    return {destroy(){alive=false;node.removeEventListener('keydown',trap);if(trigger?.isConnected)trigger.focus({preventScroll:true});}};
  }
  function shortcut(event: KeyboardEvent) {
    if(event.key==='Escape'){event.preventDefault();if(showSettings)showSettings=false;else if(panel!=='office')closePanel();return;}
    if ((event.target as HTMLElement)?.closest('input,select,textarea,[role="application"]') || event.metaKey || event.ctrlKey || event.altKey) return;
    const next: Record<string,string> = {b:'board',o:'office',p:'projects',r:'roster',i:'inbox'};
    if(event.key.toLowerCase()==='c'){event.preventDefault();showSettings=false;focusedEmployee=null;sidebarPreference=true;panel='office';return;}
    if (next[event.key.toLowerCase()]) { event.preventDefault(); showSettings=false;panel = next[event.key.toLowerCase()]; }
  }
  $: visibleProjects = projects.filter((project) => project.name.toLowerCase().includes(query.toLowerCase()));
  $: colleague = staff.find(person => person.employee_id === focusedEmployee?.employee_id) || null;
  $: pending = inbox.filter((request) => request.status === 'pending');
</script>

<svelte:window onkeydown={shortcut} />
<svelte:head><meta name="theme-color" content="#111827" /><title>Pixel Harness · office</title></svelte:head>
<main class:reduce-motion={Boolean(prefs.reduced_motion)} class={`treatment-${prefs.map_treatment}`}>
  <header class="appbar">
    <nav aria-label="Office navigation">
      {#each [{id:'coworkers',label:'Coworkers',key:'C'},{id:'board',label:'Task board',key:'B'},{id:'office',label:'Office',key:'O'},{id:'roster',label:'Roster',key:'R'},{id:'inbox',label:'Inbox',key:'I'},{id:'projects',label:'Projects',key:'P'}] as item}
        <button class:active={item.id==='coworkers'?panel==='office'&&!colleague&&sidebarOpen:panel===item.id} onclick={() => { if(item.id==='coworkers'){focusedEmployee=null;sidebarPreference=true;panel='office';}else panel=item.id; }} aria-label={item.label} title={`${item.label} (${item.key})`}><Icon name={item.id==='coworkers'?'roster':item.id==='board'?'history':item.id}/><span class="nav-label">{item.label}</span>{#if item.id==='inbox'&&pending.length}<b>{pending.length}</b>{/if}</button>
      {/each}
      <button aria-label="Assignment history" title="Assignment history" onclick={()=>{panel='roster';editing=colleague;}}><Icon name="history"/><span class="nav-label">History</span></button>
      <button class:active={showSettings} aria-label="Room settings" title="Room settings" onclick={()=>showSettings=!showSettings}><Icon name="settings"/><span class="nav-label">Settings</span></button>
    </nav>
  </header>
  {#if error}<p class="error" role="alert">{error}</p>{/if}

    <section class="office-layout" class:sidebar-closed={!sidebarOpen} class:behind-panel={panel!=='office'} inert={panel!=='office'||showSettings}>
      <section class="office-stage" class:panel-visible={sidebarOpen}>
        <button class="sidebar-toggle" aria-label={sidebarOpen ? 'Hide coworker panel' : 'Show coworker panel'} aria-expanded={sidebarOpen} aria-controls="coworker-panel" onclick={()=>sidebarPreference=!sidebarOpen}><Icon name="roster"/><span>Coworkers</span><Icon name={sidebarOpen?'collapse':'expand'}/></button>
        <Office {poseOverrides} active={panel==='office'&&!showSettings} staff={staff.filter(p=>p.environment?.kind==='local')} reduced={Boolean(prefs.reduced_motion)} selectedId={colleague?.employee_id} navigate={(next, person) => { if(person) {openPerson(person);} else panel=next; }} />
        <div class="world-bar"><span>{selected?.name || 'Your office'}</span><small>{staff.length} colleagues · {selected?.tasks?.length || 0} tasks</small><button onclick={()=>showSettings=!showSettings} aria-label="Change room atmosphere"><Icon name="settings"/></button></div>
        <button class="mail-tray" onclick={()=>panel='inbox'} aria-label={`Mailbox, ${pending.length} pending requests`}><span class="mail-icon"><Icon name="inbox"/>{#if pending.length}<i></i>{/if}</span><span class="paper cream"></span><span class="paper moss"></span><span class="paper clay"></span><small>{pending.length ? `${pending.length} awaiting attention` : 'Mailbox · all quiet'}</small></button>
      </section>
      <aside class="studio-sidebar" id="coworker-panel" hidden={!sidebarOpen}>
        <section class="dialogue-frame">
          <div class="frame-bar"><span class="frame-icon"><Icon name={colleague?'expand':'roster'}/></span>{#if colleague}<button class="back-to-coworkers" onclick={()=>{focusedEmployee=null;selectedTaskId='';historicalExecution=null;dock='activity';}}>‹ Coworkers</button>{/if}<span class="frame-caption">{colleague ? 'Colleague' : 'Coworkers'}</span><span class="frame-dots" aria-hidden="true">▪ ▪</span><button class="sidebar-close" aria-label="Collapse coworker panel" onclick={()=>sidebarPreference=false}><Icon name="collapse"/></button></div>
          {#if !colleague}
            <SidebarCoworkers {staff} {board} {openPerson}/>
          {:else}
          <div class="conversation">
            {#key colleague?.employee_id}<div class="speaker" in:fade={{duration:motionOff?0:140}}><div class="portrait-crop"><Sprite character kind="bust" recipe={colleague?.appearance_recipe || {}}/></div><div><h1>{colleague?.name || 'Welcome in.'}</h1><p>{colleague?.title || 'Make yourself at home'}</p><small>{colleague?.environment?.kind==='coder'?'Remote · Coder · not connected':'In office · Local'} · {board.find(t=>t.task_id===colleague?.assignment?.task_id)?.working_state || 'Available'}</small></div></div>{/key}
            {#key colleague?.employee_id}<div class="dialogue-body">
              <div class="speech">{#if viewExecution}<small>Session {viewExecution.session_id} · {viewExecution.continuation_state}</small>{/if}{viewExecution ? `${viewExecution.employee_name} owns the Codex session for ${viewExecution.task_title}.` : colleague?.assignment ? `Current assignment: ${colleague.assignment.task_title}` : colleague ? `${colleague.name} is available. Open your project to plan their next assignment.` : 'Start with a project and bring your first colleague into the office.'}</div>
              <button class="speech choice" onclick={()=>panel='projects'}>{colleague?.assignment ? 'Review this assignment' : selected ? 'Open project & tasks' : 'Create a project'}<span>▶</span></button>
              <div class="speech history-bubble"><p class="bubble-label">{colleague ? 'Assignment history' : 'The office'}</p>{#if colleague?.history?.some((item:any)=>item.ended_at)}{#each colleague.history.filter((item:any)=>item.ended_at).slice(0,1) as assignment}<p>{assignment.task_title}<small>{assignment.ended_at ? 'Completed · colleague released' : 'Current assignment'}</small></p>{/each}{:else}<p>{colleague ? 'No completed assignments yet.' : 'Projects, people and their history are kept together on this computer.'}</p>{/if}</div>
              <div class="speech project-bubble"><span class="bubble-label">Project room</span><p>{selected?.name || 'Your office'}<small>{selected?.tasks?.filter((task:any)=>task.status!=='complete').length || 0} open tasks · {staff.length} colleagues</small></p></div>{#if colleague?.environment?.kind==='local'}<div class="pose-controls" aria-label="Coworker room activity"><span>In the room</span>{#each [{id:'seated',label:'At desk'},{id:'walking',label:'Walk'},{id:'sleeping',label:'Rest'}] as pose}<button title="Room animation only; does not change task execution" class:chosen={poseOverrides[colleague.employee_id]===pose.id} onclick={()=>poseOverrides={...poseOverrides,[colleague.employee_id]:pose.id}}>{pose.label}</button>{/each}</div>{/if}<div class="dialogue-options"><button onclick={()=>{editing=colleague;panel='roster';}}><span>▸</span>{colleague ? 'Profile & appearance' : 'Add a colleague'}</button><button onclick={()=>panel='inbox'}><span>▸</span>{pending.length ? `${pending.length} request${pending.length===1?'':'s'} in the mailbox` : 'Open the mailbox'}</button><button onclick={()=>panel='projects'}><span>▸</span>{selected?.name || 'Your projects'}</button></div>
            </div>{/key}
          </div>
          {/if}
        </section>
        <section class="terminal-frame">
          <div class="dock-tabs"><button class:chosen={dock==='activity'} onclick={()=>dock='activity'} title="Local activity"><Icon name="terminal"/><span>Local log</span></button><button class:chosen={dock==='folders'} onclick={()=>dock='folders'} title="Project folders"><Icon name="projects"/><span>Folders</span></button><button class:chosen={dock==='terminal'} onclick={()=>dock='terminal'} title="Terminal connection"><Icon name="expand"/><span>Terminal</span></button></div>
          {#key dock}<div class="dock-content" in:fade={{duration:motionOff?0:120}}>{#if dock==='activity'}<p><span class="log-muted">Codex</span> <span class="log-cream">{readiness?.state === 'ready' ? readiness.cli_version : readiness?.state || 'checking'}</span></p>{#if viewExecution}<p><span class="log-green">●</span> {viewExecution.employee_name} owns {viewExecution.task_title}</p>{#each viewExecution.events.slice(-4) as event}<p class="log-muted">{event.kind.replace('attempt.','')}</p>{/each}{:else}<p class="log-green">{readiness?.state==='ready'?'office.ready':'office.connecting'}</p><p><span class="log-muted">project</span> {selected?.name || 'none selected'}</p><p><span class="log-muted">staff</span> {staff.length} colleagues</p><p><span class="log-muted">tasks</span> {selected?.tasks?.length || 0} retained locally</p><p class="log-muted boundary">Waiting for an approved task.</p>{/if}{:else if dock==='folders'}{#each selected?.folders || [] as folder}<p class="folder-log"><span class="log-green">{folder.availability}</span><br/>{folder.display_path}</p>{:else}<p class="log-muted">No folders attached.</p>{/each}{:else if viewExecution}<div class="native-terminal" use:terminalSurface role="application" aria-label="Native Codex terminal"></div><div class="terminal-controls"><span>{viewExecution.terminal?.attached ? 'Native TUI owns keyboard input' : 'Native terminal detached; execution state retained'}</span><button disabled={viewExecution?.attempt_id !== execution?.attempt_id} onclick={stopExecution}>Stop execution</button></div><form class="follow-up" onsubmit={(event)=>{event.preventDefault();sendFollowUp();}}><input bind:value={followUp} placeholder="Send a durable follow-up" aria-label="Follow-up message"/><button disabled={!followUp.trim() || viewExecution?.attempt_id !== execution?.attempt_id}>Send</button></form>{:else}<p class="log-cream">No terminal session connected.</p><p class="log-muted">Approve a plan before launching a selected two-folder task.</p>{/if}</div>{/key}
        </section>
      </aside>
    </section>
  {#if panel !== 'office'}
    <button class="panel-backdrop" aria-label="Close panel" onclick={closePanel} transition:fade={{duration:motionOff?0:120}}></button>
    <div class="panel-sheet" role="dialog" aria-modal="true" aria-label={panel==='coworkers'?'Coworkers':panel==='board'?'Task board':panel==='projects'?'Projects':panel==='roster'?'Roster':'Inbox'} tabindex="-1" use:focusSurface in:fly={{x:8,duration:motionOff?0:160}} out:fade={{duration:motionOff?0:100}}>
      <button class="close-sheet" aria-label="Return to office" onclick={closePanel}><Icon name="close"/></button>
  {#if panel === 'board'}
    <Coworkers mode={panel} {staff} {board} {projects} {environments} {openPerson} {openTask} {mutate}/>
  {:else if panel === 'projects'}
    <section class="drawer-layout">
      <aside class="list-pane"><p class="eyebrow">DIRECT ACCESS</p><h1>Projects</h1><input bind:value={query} placeholder="Search projects" aria-label="Search projects" /> <form onsubmit={createProject}><input name="name" placeholder="New project name" required /><button>Create</button></form>{#each visibleProjects as project}<button class="project-row" class:chosen={project.project_id === selected?.project_id} onclick={() => { selected = project; roomId = 'office'; panel = 'office'; }}><strong>{project.name}</strong><small>{project.status} · {project.folders.length} folders · {project.tasks.length} tasks</small></button>{/each}</aside>
      <section class="detail-pane">{#if selected}<div class="detail-head"><div><p class="eyebrow">PROJECT ROOM</p><h1>{selected.name}</h1><p>{selected.status === 'archived' ? 'Archived records remain readable; staff have been released.' : execution ? 'One service-owned Codex session is active.' : 'Codex is ready but never launches automatically.'}</p></div><button onclick={() => archive(selected.status === 'active' ? 'archive' : 'reopen')}>{selected.status === 'active' ? 'Archive project' : 'Reopen project'}</button></div><div class="columns"><section><h2>Attached folders</h2><button onclick={attachNativeFolder}>Choose local folder…</button><p class="empty">Attach at least two local folders to launch Codex. Nothing is copied or uploaded.</p><ul>{#each selected.folders as folder}<li><code>{folder.display_path}</code><small>{folder.availability}</small></li>{/each}</ul></section><section><h2>Tasks</h2>{#if selected.folders.length}<form onsubmit={addTask} class="task-form"><input name="title" placeholder="Task objective" required /><select name="employee_id"><option value="">Unassigned</option>{#each staff.filter((person) => !person.assignment && person.active) as person}<option value={person.employee_id}>{person.name}</option>{/each}</select><fieldset><legend>Task folders · select at least two and choose one primary to enable Codex</legend>{#each selected.folders.filter((folder: any) => folder.availability === 'available') as folder}<label><input name="folder_ids" type="checkbox" value={folder.folder_id} /> {folder.display_path}</label><label><input name="primary_folder_id" type="radio" value={folder.folder_id} /> primary</label>{/each}</fieldset><button>Create task</button></form>{:else}<p class="empty">Choose local folders before creating a task.</p>{/if}<ul>{#each selected.tasks as task}<li class="task-row" id={`task-${task.task_id}`}><strong>{task.title}</strong><small>{board.find(t=>t.task_id===task.task_id)?.working_state || task.status} · {task.assignments.map((assignment: any) => assignment.employee_name).join(', ') || 'unassigned'}</small>{#if task.status === 'complete'}<p class="execution-status">This task is complete. Reopen it to restore its previous assignment.</p><button onclick={() => reopenTask(task)}>Reopen task</button>{:else}<p class="execution-status">{board.find(t=>t.task_id===task.task_id)?.blocking_reason || 'Ready for explicit launch.'}</p><label class="execution-request">Explicit Codex request <textarea bind:value={launchPrompt} disabled={!task.assignments.length || task.folders.length < 2} placeholder="Describe the work to run in these selected folders."></textarea></label>{#if !task.assignments.length}<p class="execution-status">Launch unavailable: assign a colleague when creating the task.</p>{:else if task.folders.length < 2}<p class="execution-status">Launch unavailable: this task has {task.folders.length} selected folder. Codex execution requires at least two.</p>{#if selected.folders.filter((folder:any)=>folder.availability==='available').length >= 2}<button onclick={() => useAllProjectFolders(task)}>Use all project folders</button>{/if}{:else if readiness?.state !== 'ready'}<p class="execution-status">Launch unavailable: {readiness?.detail || 'Codex is not ready.'}</p>{/if}<button disabled={Boolean(execution)||readiness?.state!=='ready'||!task.assignments.length||task.folders.length<2} onclick={() => launch(task)}>{execution ? 'Another execution owns Codex' : 'Launch Codex'}</button><button class="secondary" onclick={() => complete(task)}>Complete task (simulation)</button>{/if}</li>{/each}</ul></section></div>{:else}<p class="empty">Create your first project to open its room.</p>{/if}</section>
      {#if selected}<section class="plan-review"><h2>Plan approval</h2>{#each selected.tasks.filter((task:any)=>task.status!=='complete') as task}<div class="plan-card"><strong>{task.title}</strong><form class="plan-form" onsubmit={(event)=>createPlan(event,task)}><input name="summary" placeholder="Proposed plan summary" required /><textarea name="milestones" placeholder="Milestones, one per line"></textarea><textarea name="acceptance" placeholder="Acceptance criteria, one per line"></textarea><button>Propose plan version</button></form>{#each task.plans || [] as plan}<div class="plan-card"><strong>v{plan.version} · {plan.status}</strong><p>{plan.summary}</p><small>{plan.milestones.length} milestones · {plan.acceptance.length} acceptance criteria</small>{#if plan.status==='pending'}<button onclick={()=>approvePlan(plan)}>Approve this version</button>{/if}</div>{/each}</div>{/each}</section>{/if}
      {#if selected}<section class="guidance-review"><h2>Project guidance</h2><p class="metadata">Active guidance is scoped to this project or a selected task; new sessions receive only applicable records with provenance.</p><form class="guidance-form" onsubmit={(event)=>saveGuidance(event)}><input name="content" placeholder="Project guidance" required /><input name="provenance" placeholder="Provenance, e.g. user direction" required /><button>Add project guidance</button></form>{#each selected.tasks as task}<article class="guidance-task"><h3>{task.title}</h3><form class="guidance-form" onsubmit={(event)=>saveGuidance(event,task.task_id)}><input name="content" placeholder="Task-specific guidance" required /><input name="provenance" placeholder="Provenance" required /><button>Add task guidance</button></form>{#each task.guidance || [] as guidance}<div class="guidance-card"><p>{guidance.content}</p><small>{guidance.scope} · {guidance.provenance} · active</small><form class="guidance-form correction" onsubmit={(event)=>saveGuidance(event,guidance.scope==='task'?task.task_id:undefined,guidance.guidance_id)}><input name="content" placeholder="Correct this guidance" required /><input name="provenance" value="correction" required /><button>Correct</button><button type="button" onclick={()=>retireGuidance(guidance)}>Retire</button></form></div>{/each}</article>{/each}</section>{/if}
      {#if execution}<button class="active-terminal-cta" onclick={openActiveTerminal}>Open active Codex terminal</button>{/if}
    </section>
  {:else if panel === 'roster'}
    <section class="drawer-layout"><aside class="list-pane"><p class="eyebrow">PERSISTENT STAFF</p><h1>Roster</h1><form onsubmit={createStaff}><input name="name" placeholder="Name" required /><input name="title" placeholder="Role" /><button>Add staff</button></form>{#each staff as person}<button class="person-row" class:chosen={editing?.employee_id === person.employee_id} onclick={() => editing = person}><span class="roster-sprite"><Sprite character kind="standing" recipe={person.appearance_recipe}/></span><span><strong>{person.name}</strong><small>{person.assignment ? `Assigned · ${person.assignment.task_title}` : 'Available'}</small></span></button>{/each}</aside><section class="detail-pane">{#if editing}<p class="eyebrow">EDITABLE COMPOSABLE RECIPE</p><h1>{editing.name}</h1><div class="avatar-preview" style={`--person:${editing.color}`}><div class="editor-sprite"><Sprite character kind="standing" recipe={editing.appearance_recipe}/></div><span>{editing.assignment ? 'Assigned' : 'Available'}</span></div><p>{editing.title} · stable employee identity; visual recipe is stored separately from name and task history.</p><form onsubmit={saveAppearance} class="recipe"><label>Body <input name="body" value={editing.appearance_recipe.body} /></label><label>Skin <select name="skin" value={editing.appearance_recipe.skin}>{#each recipes.skin as option}<option>{option}</option>{/each}</select></label><label>Hair <select name="hair" value={editing.appearance_recipe.hair}>{#each recipes.hair as option}<option>{option}</option>{/each}</select></label><label>Top <select name="top" value={editing.appearance_recipe.top}>{#each recipes.top as option}<option>{option}</option>{/each}</select></label><label>Bottom <input name="bottom" value={editing.appearance_recipe.bottom} /></label><label>Accent <select name="accent" value={editing.appearance_recipe.accent}>{#each recipes.accent as option}<option>{option}</option>{/each}</select></label><label>Accessory <input name="accessory" value={editing.appearance_recipe.accessory} /></label><button>Save appearance recipe</button></form><h2>Assignment history</h2><ul>{#each editing.history as assignment}<li><strong>{assignment.task_title}</strong><small>{assignment.project_name} · {assignment.ended_at ? 'released' : 'active assignment'}</small></li>{/each}</ul>{:else}<p class="empty">Select a staff member. Appearance is an editable recipe, never inferred from their name.</p>{/if}</section></section>
  {:else}
    <section class="inbox-shell"><header><div><p class="eyebrow">OFFICE MAILBOX</p><h1>Attention inbox</h1><p>Clarifications and revision requests are delivered to the active Codex session and retained here.</p></div><button onclick={addNotice} disabled={!execution}>Request clarification</button></header><div class="inbox-grid"><section class="request-list"><h2>Pending <span>{pending.length}</span></h2>{#each inbox as request}<button class:chosen={activeRequest?.request_id === request.request_id} onclick={() => activeRequest = request}><b>{request.kind}</b><strong>{request.summary}</strong><small>{request.project_name} · {request.employee_name || 'Office'} · {request.status}</small></button>{/each}{#if !inbox.length}<p class="empty">No requests yet. Request clarification from an active Codex session when it needs direction.</p>{/if}</section><section class="request-detail">{#if activeRequest}<p class="eyebrow">{activeRequest.source} · {activeRequest.status}</p><h2>{activeRequest.summary}</h2><p>{activeRequest.detail}</p><div class="block"><strong>What it blocks</strong><p>{activeRequest.blocks}</p></div><p class="metadata">{activeRequest.project_name} · {activeRequest.employee_name || 'Office'} · {activeRequest.task_title || 'No task linked'}</p>{#if activeRequest.status === 'pending'}<button onclick={() => resolveNotice(activeRequest)}>Deliver acknowledgement and resolve</button>{/if}<button class="secondary" onclick={() => { if (activeRequest.task_id) { selected = projects.find(project => project.project_id === activeRequest.project_id) || selected; panel = 'projects'; } else panel = 'office'; }}>Open linked {activeRequest.task_id ? 'task' : 'office'} </button>{:else}<p class="empty">Choose a request to see its detail and linked task.</p>{/if}</section></div><section class="history"><h2>Resolved history</h2><p>{inbox.filter((request) => request.status === 'resolved').length} resolved request(s) retained locally.</p></section></section>
  {/if}
    </div>
  {/if}
  {#if showSettings}<button class="settings-backdrop" aria-label="Dismiss room settings" onclick={()=>showSettings=false} transition:fade={{duration:motionOff?0:100}}></button><div class="settings-popover" role="dialog" aria-modal="true" tabindex="-1" aria-label="Room settings" use:focusSurface={true} in:fly={{x:4,y:4,duration:motionOff?0:150}} out:fade={{duration:motionOff?0:90}}><div class="settings-title"><h2>Room atmosphere</h2><button aria-label="Close room settings" onclick={()=>showSettings=false}><Icon name="close"/></button></div><div class="treatments">{#each ['warm','cool','editorial'] as treatment}<button class:chosen={prefs.map_treatment===treatment} onclick={()=>setTreatment(treatment as 'warm'|'cool'|'editorial')}>{treatment}</button>{/each}</div><label class="toggle"><input type="checkbox" checked={Boolean(prefs.reduced_motion)} onchange={setMotion}/>Reduce motion</label></div>{/if}

</main>

